package com.bank.vocab.service;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class VocabularyService {
    private static final Logger log = Logger.getLogger(VocabularyService.class.getName());

    public List<String> uniqueWords(List<String> sentences) {
        log.info(() -> "Building vocabulary from " + sentences.size() + " sentences");
        return sentences.stream()
                // Split each sentence on whitespace, stream the words, flatten all into one stream.
                .flatMap(sentence -> Arrays.stream(sentence.split("\\s+")))
                .map(word -> word.toLowerCase(Locale.ROOT))  // normalise case
                .distinct()                                  // keep each word once
                .collect(Collectors.toList());
    }
}
